Approach 3(Using Loop): To solve the problem follow the below idea:

Initialize a counter variable i to 0.Use a while loop to iterate over the first n terms of the series, printing out each term and multiplying the previous term by the common ratio to get the next term.Below is the implementation of the above approach:



            C++

    #include <iostream>
using namespace std;

void printGP(int a, int r, int n) {
    for (int i = 0; i < n; i++) {
        cout << a << " ";
        a *= r;
    }
}

int main() {
    // Starting number
    int a = 2;

    // Common ratio
    int r = 3;

    // Nth term to be found
    int n = 5;

    cout << "GP Series: ";
    // Function call
    printGP(a, r, n);

    return 0;
}


            Java

    // java program to find nth term
// of geometric progression
import java.io.*;
import java.lang.*;

class GFG {

    public static void printGP(int a, int r, int n)
    {
        int i = 0;
        while (i < n) {
            System.out.print(a + " ");
            a *= r;
            i++;
        }
    }

    // Driver code
    public static void main(String[] args)
    {
        // starting number
        int a = 2;

        // Common ratio
        int r = 3;

        // N th term to be find
        int n = 5;

        System.out.print("GP Series: ");
        // Function call
        printGP(a, r, n);

    }
}


